    ABS_MAG_FAINTEST: Float32 = .nan,
    POINTS_3DVectorOffset POINTS_3D: Offset = Offset()
  ) -> Offset {
    let __start = SKT.startSKT(&fbb)
    SKT.add(LAYER_ID: LAYER_ID, &fbb)
