    SKT.add(MAP_QUANTITY: MAP_QUANTITY, &fbb)
    SKT.add(MAP_QUANTITY_NAME: MAP_QUANTITY_NAME, &fbb)
    SKT.add(MAP_UNITS: MAP_UNITS, &fbb)
    SKT.add(MAP_SCALE: MAP_SCALE, &fbb)
